contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint ticketAmount) public payable {
        require(ticketAmount == 10, "ticket must be exactly 10 wei");
        require(address(this).balance >= ticketAmount, "not enough balance");

        uint bankBefore = c.bank().balance;
        uint contractBefore = address(c).balance;
        uint potBefore = c.pot();

        bool reverted;
        try c.play{value: ticketAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint bankAfter = c.bank().balance;
            uint contractAfter = address(c).balance;
            uint potAfter = c.pot();

            // General rule: on a successful play with exactly TICKET_AMOUNT,
            // either no payout occurred (pot increased by the ticket amount and remains positive),
            // or a payout occurred, in which case the bank received exactly FEE_AMOUNT
            // and the contract's balance decreased by at most FEE_AMOUNT.
            assert(
                (potAfter == potBefore + ticketAmount && bankAfter == bankBefore && contractAfter == contractBefore + ticketAmount) ||
                (bankAfter == bankBefore + 1 && contractAfter + 1 <= contractBefore + ticketAmount && potAfter == 0)
            );
        } else {
            assert(
                c.pot() == potBefore &&
                address(c).balance == contractBefore &&
                c.bank().balance == bankBefore
            );
        }
    }

    receive() external payable {}
}

